def eval_expression(expr):
    """
    Evaluates a mathematical expression following order of operations.

    Supports:
      - Basic arithmetic operators (+, -, *, /)
      - Parentheses for grouping
      - Negative numbers (e.g., "-5 + 3")
      - ZeroDivisionError when dividing by zero

    Args:
        expr (str): A valid mathematical expression string.

    Returns:
        float or int: The evaluated result of the expression.

    Raises:
        ValueError: If expression syntax is invalid.
        ZeroDivisionError: If division by zero occurs.
        SyntaxError: For malformed expressions.
    """
    def tokenize(s):
        tokens = []
        i = 0
        while i < len(s):
            if s[i].isdigit() or (s[i] == '-' and not tokens and s[i:] != '-' and i + 1 < len(s) and s[i+1].isdigit()):
                j = i
                if s[j] == '-':
                    j += 1
                while j < len(s) and s[j].isdigit():
                    j += 1
                tokens.append(('NUMBER', int(s[i:j])))
                i = j
            elif s[i] in '()+-*/':
                tokens.append(('OPERATOR', s[i]))
                i += 1
            elif s[i] == ' ':
                i += 1
            else:
                raise ValueError(f"Invalid character '{s[i]}'.")
        return tokens

    def is_right_associative(op):
        # Operators with right associativity
        return op in ['**'] if op != '**' else True

    class RPNCalculator:
        def __init__(self):
            self.stack = []

        def push(self, value):
            self.stack.append(value)

        def pop(self):
            if not self.stack:
                raise ValueError("Stack underflow.")
            return self.stack.pop()

        def evaluate(self, tokens):
            ops = ['+', '-', '*', '/']
            for i in range(len(tokens)):
                token_type, value = tokens[i]
                if token_type == 'NUMBER':
                    self.push(value)
                elif token_type == 'OPERATOR':
                    op = value
                    if not (op in ops or op == '**'):
                        raise ValueError(f"Invalid operator: {op}")
                    if op == '/':
                        divisor = self.pop()
                        if divisor == 0:
                            raise ZeroDivisionError("division by zero")
                        dividend = self.pop()
                        self.push(dividend / divisor)
                    elif op in ['+', '-', '*']:
                        b = self.pop()
                        a = self.pop()
                        self.push(self._apply_op(a, b, op))
                    elif op == '**':
                        b = self.pop()
                        a = self.pop()
                        self.push(a ** b)

            if len(self.stack) != 1:
                raise ValueError("Invalid expression.")
            return self.stack[0]

        def _apply_op(self, a, b, op):
            if op == '+': return a + b
            elif op == '-': return a - b
            elif op == '*': return a * b
            else: raise ValueError(f"Unsupported operator {op}")

    try:
        tokens = tokenize(expr)
        calc = RPNCalculator()
        # Build reverse Polish notation using shunting-yard-like approach
        output_queue, op_stack = [], []

        for i, token_type, value in enumerate(tokens):
            if token_type == 'NUMBER':
                output_queue.append(value)
            elif token_type == 'OPERATOR':
                if value == '(':
                    op_stack.append(value)
                elif value == ')':
                    while op_stack and op_stack[-1] != '(':
                        output_queue.append(op_stack.pop())
                    if not op_stack:
                        raise ValueError("Mismatched parentheses.")
                    op_stack.pop()  # Pop '('
                else:
                    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '**': 3}
                    while (op_stack and op_stack[-1] != '(' and 
                            precedence.get(op_stack[-1], 0) >= precedence[value]):
                        output_queue.append(op_stack.pop())
                    op_stack.append(value)

        while op_stack:
            if op_stack[-1] != '(':
                output_queue.append(op_stack.pop())
            else:
                raise ValueError("Mismatched parentheses.")

        if not (len(output_queue) - len(op_stack)) == 0:
            raise ValueError("Invalid expression structure.")

        # Evaluate RPN using the calculator stack method
        rpn_calc = RPNCalculator()
        for item in output_queue:
            if isinstance(item, int):
                rpn_calc.push(item)
            elif isinstance(item, float):
                rpn_calc.push(item)
            else:
                pass  # Ignore leftover ops due to prior checks

        return rpn_calc.evaluate(tokens)

    except ZeroDivisionError:
        raise
    except Exception as e:
        raise ValueError(f"Invalid expression syntax or logic: {e}")
